begin;
do $$
declare r uuid; other uuid; hr uuid:=gen_random_uuid(); employee uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); manager uuid:=gen_random_uuid(); n integer;
begin
 perform set_config('request.jwt.claim.sub','',true);
 insert into auth.users(id) values(hr),(employee),(outsider),(manager);
 insert into public.restaurants(name,slug,seat_limit) values('QA Holidays','qa-holidays-'||gen_random_uuid(),30) returning id into r;
 insert into public.restaurants(name,slug,seat_limit) values('QA Other','qa-holidays-other-'||gen_random_uuid(),30) returning id into other;
 insert into public.staff(restaurant_id,auth_user_id,name,role) values(r,hr,'QA HR','hr'),(r,employee,'QA Employee','waiter'),(other,outsider,'QA Outsider','hr'),(r,manager,'QA Manager','manager');
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',hr::text,true);
 if not app.has_capability(r,'manage_staff') or not app.has_capability(r,'manage_shifts') then raise exception 'HR access missing';end if;
 if app.has_capability(r,'manage_restaurant') or app.has_capability(r,'manage_finance') then raise exception 'HR privilege escalation';end if;
 begin update public.staff set name='Blocked manager edit' where auth_user_id=manager;raise exception 'HR changed management account';exception when insufficient_privilege then null;end;
 begin delete from public.staff where auth_user_id=manager;raise exception 'HR deleted management account';exception when insufficient_privilege then null;end;
 begin delete from public.staff where auth_user_id=hr;raise exception 'HR removed own access';exception when insufficient_privilege then null;end;
 update public.staff set name='Updated employee' where auth_user_id=employee;get diagnostics n=row_count;if n<>1 then raise exception 'HR employee access missing';end if;
 insert into public.workforce_holidays(restaurant_id,name,holiday_date,annual) values(r,'Christmas','2026-12-25',true);
 if not exists(select 1 from public.workforce_holidays where created_by=hr) then raise exception 'Holiday audit missing';end if;
 begin insert into public.workforce_holidays(restaurant_id,name,holiday_date) values(other,'Foreign','2026-12-25');raise exception 'Cross-tenant holiday insert accepted';exception when insufficient_privilege then null;end;
 begin update public.workforce_holidays set restaurant_id=other;raise exception 'Holiday reassignment accepted';exception when raise_exception then if sqlerrm='Holiday reassignment accepted' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',employee::text,true);
 if (select count(*) from public.workforce_holidays)<>1 then raise exception 'Shared holiday missing';end if;
 begin insert into public.workforce_holidays(restaurant_id,name,holiday_date) values(r,'Employee edit','2026-12-01');raise exception 'Employee created holiday';exception when insufficient_privilege then null;end;
 update public.workforce_holidays set name='Changed';get diagnostics n=row_count;if n<>0 then raise exception 'Employee updated holiday';end if;
 delete from public.workforce_holidays;get diagnostics n=row_count;if n<>0 then raise exception 'Employee deleted holiday';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if exists(select 1 from public.workforce_holidays) then raise exception 'Other workspace holiday leak';end if;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub','',true);
 update public.staff set permission_overrides='{"manage_staff":false,"manage_shifts":false}' where auth_user_id=hr;
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',hr::text,true);
 if app.has_capability(r,'manage_staff') or app.has_capability(r,'manage_shifts') then raise exception 'Explicit HR restriction bypassed';end if;
 begin insert into public.workforce_holidays(restaurant_id,name,holiday_date) values(r,'Restricted','2026-12-02');raise exception 'Restricted HR inserted holiday';exception when insufficient_privilege then null;end;
 if has_table_privilege('anon','public.workforce_holidays','select') then raise exception 'Anonymous holiday access';end if;
 execute 'reset role';
end $$;
select 'PASS: employee read-only, HR writes, audit, immutable workspace, cross-tenant isolation and revoked access' as result;
rollback;
